from html.parser import HTMLParser
import xml.etree.ElementTree as ET

class MyHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.builder = ET.TreeBuilder(insert_comments=True)
    def handle_starttag(self, tag, attrs):
        self.builder.start(tag, dict(attrs))
    def handle_endtag(self, tag):
        self.builder.end(tag)
    def handle_startendtag(self, tag, attrs):
        self.builder.start(tag, dict(attrs))
        self.builder.end(tag)
    def handle_data(self, data):
        self.builder.data(data)
    def handle_comment(self, data):
        # ET.Comment needs specific syntax in builder if supported
        self.builder.comment(data)
    def close(self):
        super().close()
        return self.builder.close()

parser = MyHTMLParser()
parser.feed('<html><head><script src="a.js"></script></head><body><img src="a.jpg" alt="img"><p>Hello</p></body></html>')
root = parser.close()
ET.dump(root)
EOF
