{"command":"cat <<'EOF' > main.go
package main

import (
	"encoding/xml"
	"fmt"
	"os"
	"strings"
)

type NodeType int

const (
	DocumentNode NodeType = iota
	ElementNode
	TextNode
	CommentNode
)

type Node struct {
	Type     NodeType
	Data     string
	Attrs    []xml.Attr
	Children []*Node
	Parent   *Node
}

func parse(r *os.File, isHTML bool) *Node {
	decoder := xml.NewDecoder(r)
	if isHTML {
		decoder.Strict = false
		decoder.AutoClose = xml.HTMLAutoClose
		decoder.Entity = xml.HTMLEntity
	}
	doc := &Node{Type: DocumentNode}
	curr := doc
	for {
		t, err := decoder.Token()
		if err != nil {
			break
		}
		switch t := t.(type) {
		case xml.StartElement:
			n := &Node{Type: ElementNode, Data: t.Name.Local, Attrs: t.Attr, Parent: curr}
			curr.Children = append(curr.Children, n)
			curr = n
		case xml.EndElement:
			if curr.Parent != nil {
				curr = curr.Parent
			}
		case xml.CharData:
			data := string(t)
			n := &Node{Type: TextNode, Data: data, Parent: curr}
			curr.Children = append(curr.Children, n)
		case xml.Comment:
			data := string(t)
			n := &Node{Type: CommentNode, Data: data, Parent: curr}
			curr.Children = append(curr.Children, n)
		}
	}
	return doc
}

func printTree(n *Node, indent int) {
	if n.Type == ElementNode {
		fmt.Printf("%s<%s>\n", strings.Repeat("  ", indent), n.Data)
		for _, c := range n.Children {
			printTree(c, indent+1)
		}
		fmt.Printf("%s</%s>\n", strings.Repeat("  ", indent), n.Data)
	} else if n.Type == TextNode {
		fmt.Printf("%s# %q\n", strings.Repeat("  ", indent), n.Data)
	}
}

func main() {
	f, _ := os.Open("css.html")
	doc := parse(f, true)
	printTree(doc, 0)
}
EOF
go run main.go"}

