		case xml.Comment:
			data := string(t)
			n := &Node{Type: CommentNode, Data: data, Parent: curr}
			curr.Children = append(curr.Children, n)
		}
	}
	return doc
}

func printTree(n *Node, indent int) {
	if n.Type == ElementNode {
		fmt.Printf("%s<%s>\n", strings.Repeat("  ", indent), n.Data)
		for _, c := range n.Children {
			printTree(c, indent+1)
		}
		fmt.Printf("%s</%s>\n", strings.Repeat("  ", indent), n.Data)
	} else if n.Type == TextNode {
		fmt.Printf("%s# %q\n", strings.Repeat("  ", indent), n.Data)
	}
}

func main() {
	f, _ := os.Open("css.html")
	doc := parse(f, true)
	printTree(doc, 0)
}
