import xml.etree.ElementTree as ET

def walk_events(el):
    yield "start", el
    if el.text and el.text.strip():
        yield "text", el.text.strip()
    for c in el:
        if str(c.tag).startswith('<function Comment'):
            yield "comment", c.text
        else:
            yield from walk_events(c)
        if c.tail and c.tail.strip():
            yield "text", c.tail.strip()
    yield "end", el

def beautify_tokens(tree, indent_str="  "):
    res = ""
    indent = 0
    last_event = None

    for event, node in walk_events(tree):
        if event == "start":
            if last_event == "start":
                res += ">\n" + indent_str * indent
            elif last_event in ("end", "comment"):
                res += "\n" + indent_str * indent
            elif last_event == "text":
                # what does it do? <root>a<child/></root> -> <root>a\n  <child/>
                res += "\n" + indent_str * indent
            else:
                res += indent_str * indent

            tag = node.tag
            res += f"<{tag}"
            for k, v in node.attrib.items():
                res += f' {k}="{v}"'

            indent += 1
            last_event = "start"

        elif event == "end":
            indent -= 1
            if last_event == "start":
                res += "/>"
            elif last_event in ("end", "comment"):
                res += "\n" + indent_str * indent + f"</{node.tag}>"
            elif last_event == "text":
                res += f"</{node.tag}>"
            last_event = "end"

        elif event == "text":
            if last_event == "start":
                res += ">"
            elif last_event in ("end", "comment"):
                res += "\n" + indent_str * indent # wait, is text indented?
            res += str(node)
            last_event = "text"

        elif event == "comment":
            if last_event == "start":
                res += ">\n" + indent_str * indent
            elif last_event in ("end", "comment"):
                res += "\n" + indent_str * indent
            elif last_event == "text":
                res += "\n" + indent_str * indent
            res += f"<!--{node}-->"
            last_event = "comment"

    res += "\n"
    return res

