import xml.etree.ElementTree as ET

def walk_events(el):
    yield "start", el
    if el.text and el.text.strip(" \t\r\n"):
        yield "text", el.text.rstrip(" \t")
    for c in el:
        if str(c.tag).startswith('<function Comment'):
            yield "comment", c.text
        else:
            yield from walk_events(c)
        if c.tail and c.tail.strip(" \t\r\n"):
            yield "text", c.tail.rstrip(" \t")
    yield "end", el

def beautify_tokens(tree, indent_str="  "):
    res = ""
    indent = 0
    last_event = None
    has_content_stack = []

    for event, node in walk_events(tree):
        if event == "start":
            if last_event == "start":
                res += ">\n" + indent_str * indent
            elif last_event in ("end", "comment", "text"):
                res += "\n" + indent_str * indent

            tag = str(node.tag)
            res += f"<{tag}"
            for k, v in node.attrib.items():
                res += f' {k}="{v}"'

            if has_content_stack:
                has_content_stack[-1] = True
            has_content_stack.append(False)

            indent += 1
            last_event = "start"

        elif event == "end":
            indent -= 1
            has_content = has_content_stack.pop()

            if not has_content:
                res += "/>"
            else:
                if last_event == "start":
                    pass # impossible
                elif last_event in ("end", "comment"):
                    res += "\n" + indent_str * indent + f"</{node.tag}>"
                elif last_event == "text":
                    res += f"</{node.tag}>"
            last_event = "end"

        elif event == "text":
            if last_event == "start":
                res += ">"
            res += str(node)
            if has_content_stack:
                has_content_stack[-1] = True
            last_event = "text"

        elif event == "comment":
            if last_event == "start":
                res += ">\n" + indent_str * indent
            elif last_event in ("end", "comment", "text"):
                res += "\n" + indent_str * indent
            res += f"<!--{node}-->"
            # does not set has_content!
            last_event = "comment"

    res += "\n"
    return res

