import json, re
def colorize_json(s):
    def repl(m):
        if m.group(1): # key
            return f'\x1b[94m{m.group(1)}\x1b[0m:'
        elif m.group(2) is not None: # string value
            return f'\x1b[32m"{m.group(2)}"\x1b[0m'
        elif m.group(3): # bracket
            return f'\x1b[33m{m.group(3)}\x1b[0m'
        return m.group(0)
    return re.sub(r'(".*?"):|"([^"]*)"|([\{\}\[\]])', repl, s)

