def to_json(obj, level=0, compact=False):
    indent_str = "" if compact else "  "
    nl = "" if compact else "\n"
    colon = ":" if compact else ": "
    if isinstance(obj, dict):
        if not obj: return "{}" if compact else "{\n\n" + indent_str * level + "}"
        lines = []
        for k in sorted(obj.keys()):
            lines.append(indent_str * (level+1) + f'"{k}"{colon}' + to_json(obj[k], level+1, compact))
        return "{" + nl + ("," + nl).join(lines) + nl + indent_str * level + "}"
