            lines.append(indent_str * (level+1) + col_key + f'"{k}"' + col_res + colon + val)
        return col_br + "{" + col_res + nl + ("," + nl).join(lines) + nl + indent_str * level + col_br + "}" + col_res
    elif isinstance(obj, list):
